import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
import './App.css';
import SessionInfo from './SessionInfo'; // Import the SessionInfo component
import Login from './Login'; // Import the Login component

// Set up axios interceptor to add auth token to all requests
axios.interceptors.request.use(
    config => {
        // Skip token for auth, health, and ping endpoints
        if (config.url.includes('/auth/') || config.url.includes('/health') || config.url.includes('/ping')) {
            return config;
        }

        // Get token from localStorage
        const token = localStorage.getItem('auth_token');
        if (token) {
            config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
    },
    error => {
        return Promise.reject(error);
    }
);

// Add response interceptor to handle auth errors
axios.interceptors.response.use(
    response => response,
    error => {
        // Handle 401 Unauthorized errors
        if (error.response && error.response.status === 401) {
            console.log('Authentication error - redirecting to login');
            // Clear auth data
            localStorage.removeItem('auth_token');
            localStorage.removeItem('user');

            // Force page reload to redirect to login
            window.location.reload();
        }
        return Promise.reject(error);
    }
);

// Server URL for backend
const SERVER_URL = process.env.REACT_APP_SERVER_URL || 'http://localhost:3001';

// Placeholder image for browser preview
const PLACEHOLDER_IMAGE = 'data:image/svg+xml;base64,';

// Defaults for the app
const POLL_INTERVAL = 10000; // Poll every 10 seconds - increased from 5s to 10s
// Add a debounce mechanism for API calls
const DEBOUNCE_DELAY = 1000; // 1 second debounce delay
// Add session creation retry constants
const SESSION_RETRY_KEY = 'session-creation-retry-count';
const SESSION_RETRY_TIMESTAMP_KEY = 'session-creation-last-attempt';
const SESSION_CACHE_KEY = 'last-valid-session-id';
const SESSION_MAX_RETRIES = 5; // Maximum number of retries in a short period
const SESSION_REQUEST_DEBOUNCE_KEY = 'session-request-debounce'; // Key for tracking recent requests
const SESSION_REQUEST_DEBOUNCE_TIME = 3000; // 3 seconds debounce time

/**
 * OpenAI MCP Client
 */
function App() {
    // Authentication state
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [user, setUser] = useState(null);

    // Core state
    const [sessionId, setSessionId] = useState(null);
    const [messages, setMessages] = useState([
        {
            role: 'assistant',
            content: 'Welcome! I\'m here to help you with your questions and tasks. How can I assist you today?',
            id: 'welcome-message',
            is_welcome: true,  // Add a flag to clearly identify the welcome message
            created_at: new Date().toISOString()
        }
    ]);
    const [inputValue, setInputValue] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [streamingContent, setStreamingContent] = useState(''); // For storing partial responses
    const [typingMessageIds, setTypingMessageIds] = useState([]); // For tracking which messages are in typing state

    // Preview state
    const [previewVisible, setPreviewVisible] = useState(true);
    const [browserImage, setBrowserImage] = useState(PLACEHOLDER_IMAGE); // For storing the browser preview image
    const [streaming, setStreaming] = useState(false);
    const [streamStatus, setStreamStatus] = useState('waiting');

    // Status messages
    const [statusMessages, setStatusMessages] = useState([{
        type: 'info',
        text: 'Initializing...',
        time: new Date().toLocaleTimeString()
    }]);
    const [showTechnicalMessages, setShowTechnicalMessages] = useState(false);
    const [rateLimited, setRateLimited] = useState(false); // Add state for rate limiting
    const [reusingSession, setReusingSession] = useState(false); // Add state for session reuse

    // Refs for more complex state management
    const messagesRef = useRef(messages);
    const loadingRef = useRef(loading);
    const sessionIdRef = useRef(sessionId);
    const streamSourceRef = useRef(null);
    const pollTimerRef = useRef(null);
    const userScrolledAwayRef = useRef(false);
    const chatContainerRef = useRef(null);
    const messagesEndRef = useRef(null);
    const inputRef = useRef(null);
    const healthCheckControllerRef = useRef(null);

    // Add a helper function to prevent rapid status changes
    const setStreamStatusWithDebounce = useCallback((newStatus) => {
        // Don't change status if locked (except for paused and error)
        if (window.streamStatusLock &&
            Date.now() - window.streamStatusLock < 3000 &&
            newStatus !== 'paused' &&
            newStatus !== 'error') {
            console.log(`STREAM DEBUG: Ignoring rapid status change to ${newStatus} due to lock`);
            return;
        }

        // Don't transition from active -> waiting
        if (streamStatus === 'active' && newStatus === 'waiting') {
            console.log('STREAM DEBUG: Preventing active -> waiting transition');
            return;
        }

        console.log(`STREAM DEBUG: Setting stream status to ${newStatus}`);
        setStreamStatus(newStatus);
    }, [streamStatus]);

    // Keep refs in sync with states
    useEffect(() => {
        messagesRef.current = messages;
    }, [messages]);

    useEffect(() => {
        loadingRef.current = loading;
    }, [loading]);

    useEffect(() => {
        sessionIdRef.current = sessionId;
    }, [sessionId]);

    /**
     * Add a status message
     */
    const addStatusMessage = useCallback((type, text) => {
        const timeString = new Date().toLocaleTimeString();
        setStatusMessages(prev => {
            const newMessages = [...prev, { type, text, time: timeString }];
            return newMessages.length > 10 ? newMessages.slice(-10) : newMessages;
        });

        // Set the rate limited state if we detect a rate limit message
        if (type === 'error' && (
            text.includes('Rate limited') ||
            text.includes('Too many requests') ||
            text.includes('Too many session')
        )) {
            setRateLimited(true);
            // Auto-clear after 60 seconds
            setTimeout(() => {
                setRateLimited(false);
            }, 60000);
        }
    }, []);

    /**
     * Remove all message history when starting a new session
     */
    const clearMessageHistory = useCallback(() => {
        if (sessionId) {
            localStorage.removeItem(`lastTimestamp-${sessionId}`);
            console.log(`Cleared message timestamp for session ${sessionId}`);
        }
    }, [sessionId]);

    /**
     * Take a screenshot
     */
    const takeScreenshot = useCallback(async () => {
        if (!sessionIdRef.current) return;

        try {
            const response = await axios.get(`${SERVER_URL}/screenshot`, {
                params: { sessionId: sessionIdRef.current, _t: Date.now() }
            });

            if (response.data && response.data.image) {
                setBrowserImage(response.data.image);
                addStatusMessage('info', 'Screenshot updated');
            }
        } catch (err) {
            addStatusMessage('warning', `Screenshot failed: ${err.message}`);
        }
    }, [addStatusMessage]);

    /**
     * Basic stream cleanup (separate from full stopStream)
     */
    const cleanupStream = useCallback(() => {
        if (streamSourceRef.current) {
            try {
                console.log('Closing stream connection');

                // Close the EventSource
                if (streamSourceRef.current.close) {
                    streamSourceRef.current.close();
                }

                // Notify server about disconnection
                const currentSession = sessionIdRef.current;
                if (currentSession) {
                    axios.post(`${SERVER_URL}/stream-disconnect`, {
                        sessionId: currentSession,
                        timestamp: Date.now()
                    }).catch(err => {
                        console.error('Failed to notify about stream disconnect:', err);
                    });
                }

                streamSourceRef.current = null;
            } catch (err) {
                console.error('Error cleaning up stream:', err);
            }
        }
    }, [addStatusMessage, takeScreenshot, setBrowserImage]);

    /**
     * Pause stream without closing connection
     */
    const pauseStream = useCallback(() => {
        console.log('Pausing stream without closing connection');

        try {
            // Store the original event handlers before removing them
            if (streamSourceRef.current) {
                const source = streamSourceRef.current;

                // Store original handlers if not already stored
                if (!source._originalHandlers) {
                    source._originalHandlers = {
                        onmessage: source.onmessage,
                        onopen: source.onopen
                    };

                    // Remove message handler to stop processing updates while paused
                    source.onmessage = null;

                    console.log('STREAM DEBUG: EventSource handlers suspended for pause');
                }
            }

            // Update UI state - use direct call to avoid debounce for pause
            setStreamStatus('paused');
            addStatusMessage('info', 'Stream paused');
        } catch (err) {
            console.error('Error pausing stream:', err);
            addStatusMessage('warning', `Stream pause encountered error: ${err.message}`);
        }
    }, [addStatusMessage]);

    /**
     * Authentication helper functions
     */
    const handleLoginSuccess = useCallback((userData) => {
        setUser(userData);
        setIsAuthenticated(true);

        // Immediately set session ID from localStorage after login
        const loginSessionId = localStorage.getItem('session_id');
        if (loginSessionId) {
            console.log('LOGIN DEBUG: Setting session ID immediately after login:', loginSessionId);
            setSessionId(loginSessionId);
        } else {
            console.warn('LOGIN DEBUG: No session ID found in localStorage after login');
        }
    }, [setSessionId]);

    const handleLogout = useCallback(() => {
        // Clear all localStorage items
        localStorage.clear();
        setUser(null);
        setIsAuthenticated(false);
        setSessionId(null);
        setMessages([
            {
                role: 'assistant',
                content: 'You have been logged out. Please log in to continue.',
                id: 'logout-message',
                created_at: new Date().toISOString()
            }
        ]);
        cleanupStream();
    }, [cleanupStream]);

    const getAuthHeaders = useCallback(() => {
        const token = localStorage.getItem('auth_token');
        return token ? { 'Authorization': `Bearer ${token}` } : {};
    }, []);

    // Check for authentication on initial load
    useEffect(() => {
        const token = localStorage.getItem('auth_token');
        const userData = localStorage.getItem('user');

        if (token && userData) {
            try {
                setUser(JSON.parse(userData));
                setIsAuthenticated(true);
            } catch (e) {
                console.error('Error parsing user data', e);
                handleLogout();
            }
        }
    }, [handleLogout]);

    /**
     * Initialize session
     */
    useEffect(() => {
        // Only proceed if authenticated
        if (!isAuthenticated) {
            return;
        }

        // Check if we already have a session ID from login
        const loginSessionId = localStorage.getItem('session_id');

        if (loginSessionId) {
            console.log('INIT DEBUG: Using session created during login:', loginSessionId);
            setSessionId(loginSessionId);

            // Also cache it for potential future reuse
            try {
                localStorage.setItem(SESSION_CACHE_KEY, loginSessionId);
                console.log('INIT DEBUG: Cached login session ID');
            } catch (e) {
                console.error('Error caching login session ID:', e);
            }

            // Initialize tools with a small delay
            setTimeout(async () => {
                try {
                    await axios.get(`${SERVER_URL}/init`);

                    // Set stream status to waiting - this will trigger auto-start
                    console.log('INIT DEBUG: Setting stream status to waiting to trigger auto-start');
                    setStreamStatus('waiting');

                    // Take initial screenshot with a small delay
                    setTimeout(() => {
                        takeScreenshot();
                    }, 500);
                } catch (error) {
                    console.error('Error initializing tools:', error);
                }
            }, 1000);

            return; // Exit early since we're using the login session
        }

        // Check if a session request was made recently (in session storage)
        const checkRecentSessionRequest = () => {
            try {
                const lastRequestTime = parseInt(localStorage.getItem(SESSION_REQUEST_DEBOUNCE_KEY) || '0', 10);
                const now = Date.now();
                // If a request was made in the last 3 seconds
                if (now - lastRequestTime < SESSION_REQUEST_DEBOUNCE_TIME) {
                    console.log(`INIT DEBUG: Session request made ${now - lastRequestTime}ms ago, skipping duplicate request`);
                    return true;
                }
                return false;
            } catch (e) {
                console.error('Error checking session request debounce:', e);
                return false;
            }
        };

        // Mark that we've made a session request
        const markSessionRequest = () => {
            try {
                localStorage.setItem(SESSION_REQUEST_DEBOUNCE_KEY, Date.now().toString());
                console.log('INIT DEBUG: Marked session request timestamp');
            } catch (e) {
                console.error('Error marking session request timestamp:', e);
            }
        };

        // Get the last session from localStorage if available
        const getCachedSession = () => {
            try {
                const cachedSession = localStorage.getItem(SESSION_CACHE_KEY);
                if (cachedSession) {
                    console.log('INIT DEBUG: Found cached session:', cachedSession);
                    return cachedSession;
                }
            } catch (e) {
                console.error('Error reading cached session:', e);
            }
            return null;
        };

        // Store session ID in cache for potential reuse
        const cacheSessionId = (id) => {
            if (id) {
                try {
                    localStorage.setItem(SESSION_CACHE_KEY, id);
                    console.log('INIT DEBUG: Cached session ID:', id);
                } catch (e) {
                    console.error('Error caching session ID:', e);
                }
            }
        };

        // Check if we've had too many retries recently
        const checkRetryLimits = () => {
            try {
                // Get retry count and last retry timestamp
                const retryCount = parseInt(localStorage.getItem(SESSION_RETRY_KEY) || '0', 10);
                const lastRetryTimestamp = parseInt(localStorage.getItem(SESSION_RETRY_TIMESTAMP_KEY) || '0', 10);
                const now = Date.now();

                // If it's been less than 1 minute and we've exceeded the retry limit
                if (now - lastRetryTimestamp < 60000 && retryCount >= SESSION_MAX_RETRIES) {
                    console.log('INIT DEBUG: Too many session creation attempts in short period');
                    return true;
                }

                // If it's been more than 1 minute, reset the counter
                if (now - lastRetryTimestamp > 60000) {
                    localStorage.setItem(SESSION_RETRY_KEY, '0');
                }

                return false;
            } catch (e) {
                console.error('Error checking retry limits:', e);
                return false;
            }
        };

        // Increment retry counter in localStorage
        const incrementRetryCounter = () => {
            try {
                const currentCount = parseInt(localStorage.getItem(SESSION_RETRY_KEY) || '0', 10);
                localStorage.setItem(SESSION_RETRY_KEY, (currentCount + 1).toString());
                localStorage.setItem(SESSION_RETRY_TIMESTAMP_KEY, Date.now().toString());
                console.log(`INIT DEBUG: Incremented retry counter to ${currentCount + 1}`);
            } catch (e) {
                console.error('Error incrementing retry counter:', e);
            }
        };

        // Create a session with debounce
        const createSession = async () => {
            try {
                console.log('INIT DEBUG: Creating new session...');

                // Check if a session request was made recently
                if (checkRecentSessionRequest()) {
                    console.log('INIT DEBUG: Debouncing session request - too soon after previous request');
                    // Try to use cached session if available
                    const cachedSession = getCachedSession();
                    if (cachedSession) {
                        console.log('INIT DEBUG: Using cached session due to debounce:', cachedSession);
                        setSessionId(cachedSession);
                        addStatusMessage('info', 'Reusing previous session');

                        // Set reusing session state to show a notification
                        setReusingSession(true);
                        // Auto-clear after a delay
                        setTimeout(() => {
                            setReusingSession(false);
                        }, 5000);

                        return;
                    }
                    // Otherwise just abort this request
                    return;
                }

                // Mark that we're making a request now
                markSessionRequest();

                // Clear any previous message history
                if (sessionId) {
                    clearMessageHistory();
                }

                // Add a prevention against creating multiple sessions in quick succession
                if (createSession.isCreating) {
                    console.log('INIT DEBUG: Session creation already in progress, aborting duplicate request');
                    return;
                }

                // Check if we've hit the retry limit
                if (checkRetryLimits()) {
                    const cachedSession = getCachedSession();
                    if (cachedSession) {
                        console.log('INIT DEBUG: Using cached session due to retry limits:', cachedSession);
                        setSessionId(cachedSession);
                        addStatusMessage('warning', 'Too many session requests. Using previous session if available.');
                        // Still update the counter even when using cached session
                        incrementRetryCounter();
                        return;
                    }

                    // If no cached session but we're rate limited, show error
                    setError('Too many session creation attempts. Please wait a moment before refreshing.');
                    addStatusMessage('error', 'Rate limited: Please wait 60 seconds before trying again');
                    incrementRetryCounter();
                    return;
                }

                // Set flag to prevent duplicate requests
                createSession.isCreating = true;

                // Increment retry counter in localStorage
                incrementRetryCounter();

                // Store the current attempt count
                createSession.attemptCount = (createSession.attemptCount || 0) + 1;

                try {
                    const response = await axios.post(`${SERVER_URL}/session`, {}, {
                        timeout: 10000,  // 10 second timeout
                        headers: {
                            'X-Request-ID': `session-${Date.now()}`,  // Add unique request ID
                            'X-Client-Version': '1.0.0'  // Add version for tracking
                        }
                    });

                    if (response.data.success) {
                        console.log('INIT DEBUG: Session created successfully:', response.data.sessionId);
                        setSessionId(response.data.sessionId);
                        addStatusMessage('success', `Session created: ${response.data.sessionId}`);
                        createSession.attemptCount = 0; // Reset attempt count on success

                        // Cache the successful session ID
                        cacheSessionId(response.data.sessionId);

                        // Initialize tools with a small delay to prevent request flooding
                        console.log('INIT DEBUG: Initializing tools...');
                        setTimeout(async () => {
                            try {
                                await axios.get(`${SERVER_URL}/init`);

                                // Set stream status to waiting - this will trigger auto-start
                                console.log('INIT DEBUG: Setting stream status to waiting to trigger auto-start');
                                setStreamStatus('waiting');

                                // Take initial screenshot with a small delay
                                setTimeout(() => {
                                    takeScreenshot();

                                    // Directly try to start the stream after taking the screenshot
                                    console.log('INIT DEBUG: Explicitly starting stream after screenshot');
                                    if (sessionId && !streaming) {
                                        // Replace direct call to startStream with setStreamStatus
                                        console.log('INIT DEBUG: Setting status to waiting to trigger stream start');
                                        setStreamStatus('waiting');
                                        addStatusMessage('info', 'Starting browser stream...');
                                    }
                                }, DEBOUNCE_DELAY);
                            } catch (toolErr) {
                                console.error('INIT DEBUG: Error initializing tools:', toolErr);
                                addStatusMessage('error', `Tool initialization error: ${toolErr.message}`);
                            }
                        }, DEBOUNCE_DELAY);
                    } else {
                        setError(`Error creating session: ${response.data.error}`);
                    }
                } catch (err) {
                    console.error('INIT DEBUG: Error creating session:', err);

                    // Handle rate limiting specially
                    if (err.response && err.response.status === 429) {
                        console.log('INIT DEBUG: Rate limited (429), will retry with backoff');
                        setError('Rate limited when creating session. Will retry automatically.');
                        addStatusMessage('warning', 'Rate limited when creating session, retrying in a moment...');

                        // Set the rate limited state
                        setRateLimited(true);
                        // Auto-clear after a delay
                        setTimeout(() => {
                            setRateLimited(false);
                        }, 60000);

                        // Check if we have a cached session we can use as fallback
                        const cachedSession = getCachedSession();
                        if (cachedSession && createSession.attemptCount > 1) {
                            console.log('INIT DEBUG: Using cached session after rate limit:', cachedSession);
                            setSessionId(cachedSession);
                            addStatusMessage('info', 'Using previous session due to rate limiting');
                            createSession.isCreating = false;
                            return;
                        }

                        // Calculate exponential backoff delay (2s, 4s, 8s, 16s, etc.)
                        // Increased the base delay to reduce server load
                        const backoffDelay = Math.min(Math.pow(2, createSession.attemptCount) * 1000, 30000);

                        // Schedule retry with backoff
                        setTimeout(() => {
                            // Reset the creation flag so the retry can proceed
                            createSession.isCreating = false;
                            // Try again
                            createSession();
                        }, backoffDelay);
                        return; // Exit early to keep isCreating flag true until retry
                    }

                    setError(`Failed to create session: ${err.message}`);
                }
            } catch (err) {
                console.error('INIT DEBUG: Fatal error in session creation:', err);
                setError(`Failed to create session: ${err.message}`);
            } finally {
                // Clear the creation flag after a minimum delay
                setTimeout(() => {
                    createSession.isCreating = false;
                }, 5000); // Increased from 3s to 5s between session creation attempts
            }
        };

        // Only create a session if we don't already have one
        if (!sessionId) {
            const cachedSession = getCachedSession();

            // Try to validate cached session first if available
            if (cachedSession) {
                console.log('INIT DEBUG: Validating cached session:', cachedSession);

                // Check if the session is still valid
                axios.get(`${SERVER_URL}/health?sessionId=${cachedSession}`)
                    .then(response => {
                        if (response.data && response.data.success) {
                            console.log('INIT DEBUG: Cached session is valid, using it');
                            setSessionId(cachedSession);
                            addStatusMessage('info', 'Reusing previous session');

                            // Set reusing session state to show a notification
                            setReusingSession(true);
                            // Auto-clear after a delay
                            setTimeout(() => {
                                setReusingSession(false);
                            }, 5000);
                        } else {
                            console.log('INIT DEBUG: Cached session is invalid, creating new one');
                            createSession();
                        }
                    })
                    .catch(err => {
                        console.log('INIT DEBUG: Error validating cached session:', err.message);
                        // If 404, the session doesn't exist anymore
                        if (err.response && err.response.status === 404) {
                            localStorage.removeItem(SESSION_CACHE_KEY);
                        }
                        createSession();
                    });
            } else {
                createSession();
            }
        }

        // Clean up on unmount
        return () => {
            if (pollTimerRef.current) clearTimeout(pollTimerRef.current);
            if (streamSourceRef.current) streamSourceRef.current.close();
        };
    }, [isAuthenticated, setSessionId, setStreamStatus, takeScreenshot]); // Add isAuthenticated to dependencies

    /**
     * Find the last message with a specific role
     */
    const findLastMessage = useCallback((messages, role) => {
        for (let i = messages.length - 1; i >= 0; i--) {
            if (messages[i].role === role) return messages[i];
        }
        return null;
    }, []);

    /**
     * Check if the response is complete (client-side heuristic)
     * This is used as a fallback if the server doesn't provide an explicit isDone flag
     */
    const isResponseComplete = useCallback((messages) => {
        const lastAssistant = findLastMessage(messages, 'assistant');
        if (!lastAssistant) {
            console.log('IS_COMPLETE: No assistant message found, response not complete');
            return false;
        }

        console.log('IS_COMPLETE: Checking assistant message:', {
            id: lastAssistant.id,
            finish_reason: lastAssistant.finish_reason,
            has_tool_calls: !!lastAssistant.tool_calls,
            tool_call_count: lastAssistant.tool_calls?.length || 0
        });

        // Check for explicit completion signal
        if (lastAssistant.finish_reason === 'stop') {
            console.log('IS_COMPLETE: Message has finish_reason=stop, returning true');

            // Ensure all typing indicators are removed when a complete response is detected
            setTimeout(() => {
                setTypingMessageIds([]);
                setMessages(current => current.filter(m => !m.is_typing));
                if (typingTimerRef.current) {
                    clearTimeout(typingTimerRef.current);
                    typingTimerRef.current = null;
                }
            }, 0);

            return true;
        }

        // Find the last user message
        const lastUser = findLastMessage(messages, 'user');
        if (!lastUser) {
            // No user message, likely just system messages or initial state
            return false;
        }

        // Find the index of the last user message
        const lastUserIndex = messages.findIndex(m => m === lastUser);

        // Check if there's at least one assistant message after the last user message
        const hasAssistantAfterUser = messages.some((m, i) =>
            i > lastUserIndex && m.role === 'assistant' && !m.is_typing
        );

        // Tool call completion logic
        if (lastAssistant.tool_calls && lastAssistant.tool_calls.length > 0) {
            const toolCallIds = lastAssistant.tool_calls.map(tc => tc.id);
            const toolResponses = messages.filter(m =>
                (m.role === 'tool' || m.role === 'function') &&
                toolCallIds.includes(m.tool_call_id)
            );

            console.log('IS_COMPLETE: Tool call check', {
                toolCallCount: lastAssistant.tool_calls.length,
                responseCount: toolResponses.length,
                allResponsesReceived: toolResponses.length === lastAssistant.tool_calls.length,
                hasAssistantAfterUser
            });

            // All tool calls have been responded to
            if (toolResponses.length === toolCallIds.length) {
                // Find last tool response index
                const lastToolIndex = messages.findIndex(m => m === toolResponses[toolResponses.length - 1]);

                // Check for follow-up assistant message after tools
                const hasFollowUp = messages.some((m, i) => i > lastToolIndex && m.role === 'assistant');
                console.log('IS_COMPLETE: Follow-up check', { lastToolIndex, hasFollowUp });

                if (hasFollowUp) {
                    return true;
                }
            }
        } else if (hasAssistantAfterUser) {
            // If there are no tool calls but there is an assistant message after the last user
            // and it's been more than 5 seconds since the message was created, consider it complete
            const assistantMessages = messages.filter((m, i) =>
                i > lastUserIndex && m.role === 'assistant' && !m.is_typing
            );

            if (assistantMessages.length > 0) {
                const lastAssistantAfterUser = assistantMessages[assistantMessages.length - 1];

                // If the assistant message has content and it's been more than 5 seconds, consider it complete
                if (lastAssistantAfterUser.content && lastAssistantAfterUser.created_at) {
                    const messageTime = new Date(lastAssistantAfterUser.created_at).getTime();
                    const currentTime = Date.now();
                    const timeSinceMessage = currentTime - messageTime;

