                } else if (response.data.isDone === false) {
                    // Explicitly mark as not done if server says so
                    console.log('POLL: Server signaled response is not complete (isDone=false), continuing polling');
                    loadingRef.current = true; // Ensure we keep polling
                }

                // Continue with existing logic as fallback
                // Check if response is complete using client-side heuristics
                const responseComplete = isResponseComplete(response.data.messages || []);
                if (responseComplete) {
                    console.log('POLL: Response complete based on client-side heuristics, will stop polling');

